/**
 * The supply of a corpus Session: a graph container's declaration and const blocks, together with
 * generated weights, as one `BoundContainer`.
 *
 * The binding rules have one owner, the merge layer (`bindDeclarations` in
 * src/format/container/bind.ts). This module only lays out a block index for the generated bytes
 * (ids, parts, lengths) next to the const region's own index and hands both to the merge layer,
 * which plans every supply and checks it — a missing or surplus weight, a codec that does not fit
 * the dtype, a payload of the wrong length all fail there, with its messages.
 */

import {
  bindDeclarations,
  type BoundContainer,
  type Locator,
  type SupplyRecord,
} from "../../src/format/container/bind.ts";
import { codecEntry } from "../../src/format/container/codecs.ts";
import type {
  ConstantBinding,
  ConstBlockRecord,
  Encoding,
  WeightSupply,
} from "../../src/format/container/descriptor.ts";
import { DEFAULT_PART_BYTES } from "../../src/format/container/limits.ts";
import type { OpenedContainer } from "../../src/format/container/open.ts";
import type { IrDeclaration } from "../../src/format/ir.ts";
import type { GeneratedTensor } from "./weights.ts";

/** The graph container side of the supply (a `krg`, or the graph descriptor of a `krm`). */
export type ConstSide = {
  readonly constants: readonly ConstantBinding[];
  readonly blocks: readonly ConstBlockRecord[];
  /** Reads one const block (the opened container's `readBlock`, which verifies its sha256). */
  readonly read: (id: string) => Promise<Uint8Array<ArrayBuffer>>;
};

/** The const side of an opened container (`krg` or `krm` — both carry the graph descriptor). */
export const constSideOf = (
  container: Pick<OpenedContainer, "graph" | "readBlock">,
): ConstSide => ({
  constants: container.graph.const.constants,
  blocks: container.graph.const.blocks,
  read: (id) => container.readBlock(id),
});

/** The first part generated weights are stacked on (part 1 is the const region). */
const FIRST_WEIGHT_PART = 2;

/**
 * Builds the supply of graph `graphName`: its const initializers from `consts`, every other
 * non-shared initializer from `weights`.
 *
 * Generated weights are stacked on parts of at most {@link DEFAULT_PART_BYTES}, like a container
 * writer cuts them: Session construction submits once per part, so the part is the bound of the
 * staging memory during the upload.
 */
export const corpusSupply = (input: {
  readonly graphName: string;
  readonly declaration: IrDeclaration;
  readonly consts: ConstSide;
  readonly weights: ReadonlyMap<string, GeneratedTensor>;
}): BoundContainer => {
  const { graphName, declaration, consts, weights } = input;
  const constIds = new Set(consts.blocks.map((block) => block.id));
  const located = new Map<
    string,
    {
      readonly part: number;
      readonly record: SupplyRecord;
      readonly bytes: Uint8Array<ArrayBuffer>;
    }
  >();
  const register = (id: string, part: number, bytes: Uint8Array<ArrayBuffer>): void => {
    if (constIds.has(id) || located.has(id)) {
      throw new Error(
        `generated block id '${id}' collides with another block of the supply: rename the generated ids`,
      );
    }
    located.set(id, { part, record: { id, offset: 0, length: bytes.byteLength }, bytes });
  };

  // Null prototype: an initializer named `__proto__` must stay an own key.
  const supplies: Record<string, WeightSupply> = Object.create(null);
  let part = FIRST_WEIGHT_PART;
  let partBytes = 0;
  let serial = 0;
  for (const [name, tensor] of weights) {
    const bytes = tensor.bytes.byteLength + (tensor.scale?.byteLength ?? 0);
    if (partBytes > 0 && partBytes + bytes > DEFAULT_PART_BYTES) {
      part += 1;
      partBytes = 0;
    }
    partBytes += bytes;
    const id = `generated.${serial}`;
    serial += 1;
    register(id, part, tensor.bytes);
    const entry = codecEntry(tensor.encoding.codec);
    let encoding: Encoding;
    if (tensor.scale === undefined || entry.scaleDtype === undefined) {
      encoding = { codec: tensor.encoding.codec, packing: entry.packing };
    } else {
      register(`${id}.scale`, part, tensor.scale);
      encoding = {
        codec: tensor.encoding.codec,
        packing: entry.packing,
        rowAxis: tensor.encoding.rowAxis ?? 0,
        ...(tensor.encoding.groupSize === undefined
          ? {}
          : { groupSize: tensor.encoding.groupSize }),
        scale: { block: `${id}.scale`, dtype: entry.scaleDtype },
      };
    }
    supplies[name] = { block: id, encoding };
  }

  const constById = new Map(consts.blocks.map((block) => [block.id, block]));
  const locate: Locator = (id, by) => {
    const constBlock = constById.get(id);
    if (constBlock !== undefined) return { part: 1, record: constBlock };
    const generated = located.get(id);
    if (generated !== undefined) return { part: generated.part, record: generated.record };
    throw new Error(`${by}: block '${id}' is neither a const block nor a generated one`);
  };

  const graphs = bindDeclarations({
    graphs: { [graphName]: declaration },
    constants: consts.constants,
    binding: { [graphName]: supplies },
    locate,
  });

  return {
    graphs,
    readBlock: async (id: string): Promise<Uint8Array<ArrayBuffer>> => {
      const generated = located.get(id);
      if (generated !== undefined) return generated.bytes;
      if (!constById.has(id)) throw new Error(`block '${id}' is not part of the corpus supply`);
      return await consts.read(id);
    },
  };
};
